/*/
 * Custom CSS
 * -----------------------------------------------------------------------------
/*/

.navbar-default {
	border-bottom: solid 1px #eee;
}

.content {
	margin-top: 86px !important;
}

.topbar .topbar-left {
	text-align: left !important;
	// border-bottom: solid 1px #ebebeb;
}

.side-menu {
	padding-bottom: 64px !important;
}

#sidebar-menu {
	margin-top: 16px;
}

.btn-logout {
	position: absolute !important;
	background-color: #fff;
	left: 0;
	bottom: 0;
	width: 100%;
	display: block;
	button {
		border: none;
		outline: none;
		background-color: transparent;
		display: block;
		padding: 24px 30px;
		text-align-last: left;
	}
	i {
		margin-right: 12px;
	}
}

.footer {
	padding-left: 24px;
	padding-right: 24px;
}

.user-profile {
	display: block;
	border-radius: 50%;
	border: solid 1px $primary;
	width: 40px;
	height: 40px;
	overflow: hidden;
	&__el {
		display: block;
		width: 100%;
		height: 100%;
		background-position: center;
		background-size: cover;
	}
}

.user-avatar {
	width: 48px;
	height: 48px;
	display: inline-block;
	vertical-align: middle;
	border-radius: 50%;
	overflow: hidden;
	&__img {
		display: block;
		width: 100%;
		height: 100%;
		background-position: center;
		background-size: cover;
	}
}

.login-logo,
.dashboard-logo {
	display: block;
}

.dashboard-logo img,
.login-logo img {
	height: 40px;
	display: block;
}

.dashboard-logo {
	margin: 16px 20px;
}

.login-logo img {
	margin: 0 auto;
}

.side-menu-dropdown a {
	padding-left: 58px !important;
	position: relative;
}

.side-menu-dropdown a::before {
	content: "";
	display: inline-block;
	position: absolute;
	top: 50%;
	left: 42px;
	transform: translateY(-50%);
	width: 5px;
	height: 5px;
	border-radius: 50%;
	background-color: #435966;
}

.side-menu-dropdown .active a::before {
	background-color: $primary;
}

.wg-db {
	font-size: 0;
	&__icon,
	&__info {
		display: inline-block;
		vertical-align: middle;
	}
	&__icon {
		font-size: 24px;
		height: 56px;
		width: 56px;
		border-radius: 8px;
		background-color: transparent;
		position: relative;
		margin-right: 16px;
		i {
			position: absolute;
			top: 50%;
			left: 50%;
			transform: translate(-50%, -50%);
		}
	}
	&__title {
		font-size: 24px;
		font-weight: bold;
		margin: 0;
		margin-bottom: 2px;
	}
	&__desc {
		margin-bottom: 0;
		font-size: 16px;
		font-weight: bold;
		color: #98a6ad;
	}
	&__bg-success {
		background-color: rgba(95, 190, 170, 0.3);
		border-color: rgba(95, 190, 170, 0.4);
		color: #5fbeaa;
	}
	&__bg-info {
		background-color: rgba(52, 211, 235, 0.2);
		border-color: rgba(52, 211, 235, 0.3);
		color: #35b8e0;
	}
	&__bg-warning {
		background-color: rgba(255, 189, 74, 0.2);
		border-color: rgba(255, 189, 74, 0.3);
		color: #f9c851;
	}
	&__bg-danger {
		background-color: rgba(240, 80, 80, 0.2);
		border-color: rgba(240, 80, 80, 0.3);
		color: #ff5b5b;
	}
	&__bg-purple {
		background-color: rgba(91, 105, 188, 0.2);
		border-color: rgba(91, 105, 188, 0.3);
		color: #5b69bc;
	}
	&__text-success {
		color: #5fbeaa;
	}
	&__text-info {
		color: #35b8e0;
	}
	&__text-warning {
		color: #f9c851;
	}
	&__text-danger {
		color: #ff5b5b;
	}
}

* .c-primary {
	color: $primary;
}

.btn-icon {
	padding: 4px 8px !important;
	font-size: 16px;
}

.table > tbody > tr > td {
	vertical-align: middle;
}

.table > thead > tr > th {
	vertical-align: bottom;
	border-bottom: solid 4px;
	border-color: #ebeff2;
}

table.dataTable thead .sorting:before,
table.dataTable thead .sorting_asc:before,
table.dataTable thead .sorting_desc:before,
table.dataTable thead .sorting_asc_disabled:before,
table.dataTable thead .sorting_desc_disabled:before,
table.dataTable thead .sorting:after,
table.dataTable thead .sorting_asc:after,
table.dataTable thead .sorting_desc:after,
table.dataTable thead .sorting_asc_disabled:after,
table.dataTable thead .sorting_desc_disabled:after {
	font-family: "Roboto";
}

div#DataTables_Table_0_wrapper.dataTables_wrapper.container-fluid.dt-bootstrap4.no-footer {
	padding: 0 !important;
}
div#dataTable_wrapper .row {
	align-items: center !important;
}
.dataTables_length label {
	margin-bottom: 0 !important;
	font-size: 14px !important;
	color: #6c757d !important;
}

.datatable-custom .dataTables_filter {
	display: none;
}

table.dataTable.dtr-inline.collapsed > tbody > tr > td:first-child:before,
table.dataTable.dtr-inline.collapsed > tbody > tr > th:first-child:before {
	top: 50%;
	left: 8px;
	transform: translateY(-50%);
	line-height: 16px;
}

.dataTables_processing.card {
	box-shadow: none !important;
}

/* HTML: <div class="loader"></div> */
.table-loader {
	width: 50px;
	padding: 8px;
	margin: 0 auto;
	aspect-ratio: 1;
	border-radius: 50%;
	background: $primary;
	--_m: conic-gradient(#0000 10%, #000), linear-gradient(#000 0 0) content-box;
	-webkit-mask: var(--_m);
	mask: var(--_m);
	-webkit-mask-composite: source-out;
	mask-composite: subtract;
	animation: l3 1s infinite linear;
}

.modal-header .close {
	color: #ff5b5b !important;
	opacity: 1;
}

.modal-title {
	margin-top: 4px !important;
}

.dropify-wrapper {
	height: 160px !important;
}

.error label {
	font-size: 14px;
	color: #212529;
}

.error .form-control {
	border-color: #ff5b5b;
}

.form-alert {
	display: none;
	margin-top: 8px;
	margin-bottom: 0;
}

.error .form-alert {
	display: block;
	width: 100%;
}

.img-preview {
	display: none;
	&__el {
		margin-bottom: 10px;
		max-height: 80px;
	}
}

.account-profile {
	position: relative;
	width: 120px;
	height: 120px;
	border-radius: 50%;
	overflow: hidden;
	margin: 0 auto;
	margin-bottom: 16px;
	border: solid 1px #ebebeb;
}

.account-profile__img {
	display: block;
	width: 100%;
	height: 100%;
	object-fit: cover;
	object-position: center;
}

.account-profile__input,
.account-profile__icon {
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	height: 100%;
	z-index: 4;
	opacity: 0;
	cursor: pointer;
	transition: all 0.3s ease;
}

.account-profile__icon {
	background-color: rgba(0, 0, 0, 0.5);
	opacity: 0;
	visibility: hidden;
	z-index: 3;
	/* position: relative; */
}

.account-profile__icon .mdi {
	position: absolute;
	top: 50%;
	left: 50%;
	transform: translate(-50%, -50%);
	font-size: 32px;
	z-index: 5;
	color: #fff;
}

.account-profile__input:hover + .account-profile__icon {
	opacity: 1;
	visibility: visible;
}

.img-thumb-preview {
	max-height: 160px;
}

@keyframes l3 {
	to {
		transform: rotate(1turn);
	}
}

// skeleton loading
.skeleton {
	position: relative;
	overflow: hidden;
}

.skeleton::before {
	content: "";
	position: absolute;
	top: 0;
	right: 0;
	bottom: 0;
	left: 0;
	z-index: 1;
	background-color: #ddd;
}
.skeleton::after {
	content: "";
	position: absolute;
	top: 0;
	right: 0;
	bottom: 0;
	left: 0;
	z-index: 2;
	background-color: #ededed;
	background: linear-gradient(
			100deg,
			rgba(255, 255, 255, 0) 40%,
			rgba(255, 255, 255, 0.5) 50%,
			rgba(255, 255, 255, 0) 60%
		)
		#ededed;
	background-size: 200% 100%;
	background-position-x: 180%;
	animation: 1s loading ease-in-out infinite;
}

@keyframes loading {
	to {
		background-position-x: -20%;
	}
}

.skeleton-text {
	width: 100%;
	height: 1.8rem;
	margin-bottom: 0.5rem;
	border-radius: 0.25rem;
}

@include medium {
	#wrapper.enlarged .topbar .topbar-left,
	.topbar .topbar-left {
		position: absolute;
		left: 50%;
		transform: translateX(-50%);
		width: 232px !important;
	}
}

@include small {
	.user-profile {
		display: none;
	}

	.side-menu {
		padding-top: 0;
	}
}

@include x-small {
	.side-menu {
		display: none;
	}

	.forced .side-menu {
		display: block;
	}
}
